/**
 * The mod API declaration written beside a dev mod (F-25): what `tsc -p
 * <mod>` checks a hooks module against. The event shapes come from
 * `modApiShapes.generated.ts`; the events, nouns, sites, elements and tools
 * from the tables this engine serves now, so what it does not serve does
 * not type-check. Pure: the files' text, nothing written.
 */

import { MOD_API_SHAPES } from './modApiShapes.generated'
import { kitModuleDeclaration } from './testKit/kitDeclaration'

/** The phrase the first line of every generated file carries. A file whose
 *  first line lacks it is someone's own and is never overwritten. */
export const GENERATED_MARKER = 'Generated by Velloc for this mod; rewritten on each load, edits are lost.'

/** A tool the session offers, as the declaration types its input. */
export type DeclaredTool = { name: string; schema?: unknown; mcp: boolean }

export type ModApiTables = {
  /** The bare specifier a hooks module imports the API from. */
  specifier: string
  /** The events this engine raises. */
  events: readonly string[]
  /** Of those, the ones whose hooks are async generators. */
  streaming: readonly string[]
  /** Every implemented `noun.method`, and the ones the worker answers. */
  calls: readonly string[]
  /** The nouns the engine's own `$` may carry. */
  engineNouns: readonly string[]
  renderSites: readonly string[]
  desktopElements: readonly string[]
  tools: readonly DeclaredTool[]
}

/** The files of the types folder, by name, each beginning with the marker. */
export type ModApiFiles = Record<string, string>

const lit = (value: string): string => JSON.stringify(value)
const union = (values: readonly string[]): string =>
  values.length === 0 ? 'never' : [...new Set(values)].sort().map(lit).join(' | ')
const indent = (text: string, by = '  '): string =>
  text
    .split('\n')
    .map(line => (line === '' ? line : by + line))
    .join('\n')

/** The `$` interface: each engine noun with the methods this engine
 *  implements. `plugin` carries values, `ui.resolve` answers at once. */
function engineInterface(tables: ModApiTables): string {
  const byNoun = new Map<string, string[]>()
  for (const call of tables.calls) {
    const dot = call.indexOf('.')
    if (dot <= 0) continue
    const noun = call.slice(0, dot)
    if (!tables.engineNouns.includes(noun)) continue
    byNoun.set(noun, [...(byNoun.get(noun) ?? []), call.slice(dot + 1)])
  }
  const lines = ['export interface Engine {']
  if (tables.engineNouns.includes('plugin')) {
    lines.push('  readonly plugin: { readonly name: string; readonly root: string; readonly locale: string }')
  }
  for (const noun of [...byNoun.keys()].sort()) {
    if (noun === 'plugin') continue
    lines.push(`  readonly ${noun}: {`)
    for (const method of [...new Set(byNoun.get(noun))].sort()) {
      lines.push(
        noun === 'ui' && method === 'resolve'
          ? '    resolve(e: RenderEvent): UiElements'
          : `    ${method}(...args: any[]): Promise<any>`,
      )
    }
    lines.push('  }')
  }
  lines.push('}')
  return lines.join('\n')
}

/** The hand-off between the generated shapes and a hooks module. */
function hookVocabulary(tables: ModApiTables): string {
  return `export type RaisedEvent = ${union(tables.events)}
export type StreamingEvent = ${union(tables.streaming)}
/** A glob over event names, or a negation. */
export type EventGlob = \`\${string}*\${string}\` | \`!\${string}\`
export type RenderSite = ${union(tables.renderSites)}
export type RenderEvent = { [S in RenderSite]: ModRenderFrame & { component: S; props: ModRenderProps[S] } }[RenderSite]

/** Each tool's input by name; a mod declares its own tools by merging into this. */
export interface ToolInputs {}
type ToolName = keyof ToolInputs & string
export type ToolCall = [ToolName] extends [never]
  ? ToolCallEvent
  : { [K in ToolName]: { tool: K; tool_use_id: string; agentId?: string } & ToolInputs[K] }[ToolName]
export type ToolCheck = [ToolName] extends [never]
  ? ToolCheckEvent
  : { [K in ToolName]: { tool: K; input: ToolInputs[K]; tool_use_id?: string; agentId?: string } }[ToolName]

export type EventInput<K extends string> = K extends 'tool.call'
  ? ToolCall
  : K extends 'tool.check'
    ? ToolCheck
    : K extends 'ui.render'
      ? RenderEvent
      : K extends keyof ModEventShapes
        ? ModEventShapes[K]['e']
        : Record<string, unknown>
export type EventResult<K extends string> = K extends keyof ModEventShapes ? ModEventShapes[K]['result'] : unknown

/** The nouns a plugin adds to \`$\` at \`engine.create\`; declare them by merging. */
export interface PluginNouns {}
export type Dollar = Engine & PluginNouns

export interface Next<E, R> {
  (e: E): R
  to(e: E, tier: TargetTier): R
  readonly signal: AbortSignal
  is(pattern: string): boolean
  readonly event: string
  readonly origin: Origin
  readonly trace: readonly TraceEntry[]
  readonly budget: NextBudget
  /** In a \`.catch\` handler: why the hook failed. */
  readonly error?: HookFailure
  readonly called?: boolean
}

export type PlainHook<K extends string> = (
  $: Dollar,
  e: EventInput<K>,
  next: Next<EventInput<K>, Promise<EventResult<K>>>,
) => EventResult<K> | Promise<EventResult<K>>
export type StreamHook<K extends string> = (
  $: Dollar,
  e: EventInput<K>,
  next: Next<EventInput<K>, AsyncGenerator<unknown, EventResult<K>, unknown>>,
) => AsyncGenerator<unknown, EventResult<K>, unknown>
export type Hook<K extends string> = K extends StreamingEvent ? StreamHook<K> : PlainHook<K>

export interface Registration<K extends string> {
  catch(handler: Hook<K>): void
}
/** A partial of the event's argument the hook is called for. */
export type Matcher<E> = { [P in keyof E]?: unknown }

export interface On {
  <K extends RaisedEvent>(event: K, hook: Hook<K>): Registration<K>
  <K extends RaisedEvent>(event: K, matcher: Matcher<EventInput<K>>, hook: Hook<K>): Registration<K>
  (pattern: EventGlob, hook: Hook<string>): Registration<string>
  (pattern: EventGlob, matcher: Record<string, unknown>, hook: Hook<string>): Registration<string>
}
/** What a hooks module exports. */
export type Register = (on: On, options: Readonly<Record<string, unknown>>) => void | Promise<void>

export type ElementName = ${union(tables.desktopElements)}
export type UiElement = { readonly type: string; readonly props?: unknown; readonly children?: readonly unknown[] }
export type UiElements = {
  readonly [N in ElementName]: (props: Record<string, unknown> & { children?: unknown }) => UiElement
}

export type StateRef = { plugin: string; key: string; id?: string }
export type Atom<T> = { readonly ref: StateRef; readonly initial: T; readonly shape?: string }
export type Derived<T> = { readonly sources: readonly unknown[]; readonly compute: (...values: any[]) => T }
export function atom<T>(ref: StateRef, initial: T, options?: { shape?: string }): Atom<T>
export function derive<T>(sources: readonly unknown[], compute: (...values: any[]) => T): Derived<T>
export function memberOf<T>(family: Atom<T>, e: { requestId: string }): Atom<T>
export function read<T>($: Dollar, source: Atom<T> | Derived<T>): Promise<T>
export function update<T>($: Dollar, target: Atom<T>, change: (current: T) => T): Promise<T>`
}

/** The ambient JSX a hooks module's \`h\` and \`Fragment\` build. */
const JSX_GLOBALS = `declare function h(tag: unknown, props: unknown, ...children: unknown[]): any
declare function Fragment(props: { children?: unknown[] } | null): any
declare namespace JSX {
  type Element = any
  interface IntrinsicElements {}
}`

/** A JSON schema as a TypeScript type; `unknown` where it says nothing. */
export function schemaType(schema: unknown, depth = 0): string {
  if (depth > 8 || schema === null || typeof schema !== 'object' || Array.isArray(schema)) return 'unknown'
  const s = schema as Record<string, unknown>
  if ('const' in s) return JSON.stringify(s.const) ?? 'unknown'
  if (Array.isArray(s.enum)) {
    const members = s.enum.map(value => JSON.stringify(value)).filter((text): text is string => text !== undefined)
    return members.length > 0 ? members.join(' | ') : 'never'
  }
  for (const key of ['anyOf', 'oneOf'] as const) {
    if (Array.isArray(s[key])) return (s[key] as unknown[]).map(part => paren(schemaType(part, depth + 1))).join(' | ')
  }
  if (Array.isArray(s.allOf)) return (s.allOf as unknown[]).map(part => paren(schemaType(part, depth + 1))).join(' & ')
  if (Array.isArray(s.type)) {
    return (s.type as unknown[]).map(type => paren(schemaType({ ...s, type }, depth + 1))).join(' | ')
  }
  switch (s.type) {
    case 'string':
      return 'string'
    case 'number':
    case 'integer':
      return 'number'
    case 'boolean':
      return 'boolean'
    case 'null':
      return 'null'
    case 'array':
      return `Array<${schemaType(s.items, depth + 1)}>`
    case 'object':
      return objectType(s, depth)
    default:
      return s.properties ? objectType(s, depth) : 'unknown'
  }
}

/** `text` in parentheses when a `|` or `&` stands outside every bracket and
 *  string literal, so it can be one operand of `|` or `&`. */
function paren(text: string): string {
  let depth = 0
  let quoted = false
  for (let i = 0; i < text.length; i++) {
    const ch = text[i]!
    if (quoted) {
      if (ch === '\\') i++
      else if (ch === '"') quoted = false
    } else if (ch === '"') quoted = true
    else if ('{(<['.includes(ch)) depth++
    else if ('})>]'.includes(ch)) depth--
    else if (depth === 0 && (ch === '|' || ch === '&')) return `(${text})`
  }
  return text
}

const IDENTIFIER = /^[A-Za-z_$][A-Za-z0-9_$]*$/

function objectType(s: Record<string, unknown>, depth: number): string {
  const properties =
    s.properties && typeof s.properties === 'object' && !Array.isArray(s.properties)
      ? (s.properties as Record<string, unknown>)
      : {}
  const required = new Set(Array.isArray(s.required) ? s.required.filter(key => typeof key === 'string') : [])
  const members = Object.keys(properties).map(key => {
    const name = IDENTIFIER.test(key) ? key : JSON.stringify(key)
    return `${name}${required.has(key) ? '' : '?'}: ${schemaType(properties[key], depth + 1)}`
  })
  if (s.additionalProperties !== false) members.push('[key: string]: unknown')
  return members.length === 0 ? '{}' : `{ ${members.join('; ')} }`
}

function toolsModule(specifier: string, tools: readonly DeclaredTool[]): string {
  const names = new Set<string>()
  const members: string[] = []
  for (const tool of [...tools].sort((a, b) => a.name.localeCompare(b.name))) {
    if (names.has(tool.name)) continue
    names.add(tool.name)
    members.push(`    ${lit(tool.name)}: ${schemaType(tool.schema)}`)
  }
  return `declare module ${lit(specifier)} {
  interface ToolInputs {
${members.join('\n')}
  }
}`
}

const header = (prefix: string): string => `${prefix} ${GENERATED_MARKER}`

/** The types folder's files for `tables`. `tsconfig.json` is the one a mod's
 *  own `tsconfig.json` extends; it checks every source of the mod. */
export function buildModApiFiles(tables: ModApiTables): ModApiFiles {
  const api = [
    header('//'),
    JSX_GLOBALS,
    `declare module ${lit(tables.specifier)} {`,
    indent(MOD_API_SHAPES, '  '),
    indent(engineInterface(tables)),
    indent(hookVocabulary(tables)),
    '}',
    kitModuleDeclaration(`${tables.specifier}/testing`),
    '',
  ].join('\n')
  const tsconfig = `${header('//')}
${JSON.stringify(
  {
    compilerOptions: {
      strict: true,
      noEmit: true,
      target: 'ES2022',
      module: 'ESNext',
      moduleResolution: 'Bundler',
      lib: ['ES2022', 'DOM'],
      types: [],
      jsx: 'react',
      jsxFactory: 'h',
      jsxFragmentFactory: 'Fragment',
      skipLibCheck: false,
    },
    files: ['./api.d.ts', './builtin-tools.d.ts', './mcp-tools.d.ts'],
    include: ['../../**/*.ts', '../../**/*.tsx', '../../**/*.mts'],
  },
  null,
  2,
)}
`
  return {
    'api.d.ts': api,
    'builtin-tools.d.ts': `${header('//')}\n${toolsModule(tables.specifier, tables.tools.filter(tool => !tool.mcp))}\n`,
    'mcp-tools.d.ts': `${header('//')}\n${toolsModule(tables.specifier, tables.tools.filter(tool => tool.mcp))}\n`,
    'tsconfig.json': tsconfig,
    '.gitignore': `${header('#')}\n*\n`,
  }
}

/** Whether `text` is a file this module wrote: its first line carries the
 *  marker after a comment opener. */
export function isGeneratedFile(text: string): boolean {
  const first = text.split(/\r?\n/, 1)[0] ?? ''
  return (first.startsWith('// ') || first.startsWith('# ')) && first.endsWith(GENERATED_MARKER)
}
